const localizedStep = index => { const sourceIndex = index >= 3 && index <= 15 ? index - 2 : null; const special = index === 1 ? locales[language].language : index === 2 ? locales[language].demographics : null; return { ...steps[index], ...(special || (sourceIndex !== null ? locales[language].steps?.[sourceIndex] : null) || laterStepCopy[language]?.[index] || {}), ...(laterAnswers[language]?.[index] || {}), ...(laterNotes[language]?.[index] || {}) }; };
